cd /home/user/project && node -e "
const { createClient } = require('@supabase/supabase-js');

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

async function checkTables() {
  try {
    // Try to query the venues table
    const { data: venuesData, error: venuesError } = await supabase
      .from('venues')
      .select('id')
      .limit(1);

    console.log('venues table:', venuesError ? 'does not exist' : 'exists');

    // Try to query the party_venues table
    const { data: partyVenuesData, error: partyVenuesError } = await supabase
      .from('party_venues')
      .select('id')
      .limit(1);

    console.log('party_venues table:', partyVenuesError ? 'does not exist' : 'exists');

  } catch (e) {
    console.log('Error:', e.message);
  }
}

checkTables();
"

